import { posix } from 'node:path';
export function findSlabInstallation(io) {
    if (io.platform !== 'darwin')
        return null;
    for (const appPath of [
        '/Applications/SLAB.app',
        posix.join(io.homeDir, 'Applications', 'SLAB.app'),
    ]) {
        const executablePath = posix.join(appPath, 'Contents', 'MacOS', 'SLAB');
        if (io.existsSync(executablePath))
            return { platform: io.platform, appPath, executablePath };
    }
    return null;
}
export function isSlabInstalled(io) {
    return findSlabInstallation(io) !== null;
}
export function slabControlEndpoint(homeDir) {
    return posix.join(homeDir, '.slab', 'run', 'slab-bridge.sock');
}
